private Vector3 FindLeastVisitedPoint(Vector3 center, float radius)
{
    List<Vector3> candidates = new List<Vector3>();
    for (int i = 0; i < 20; i++)
    {
        Vector2 rand = Random.insideUnitCircle * radius;
        Vector3 pos = new Vector3(center.x + rand.x, center.y, center.z + rand.y);
        if (NavMesh.SamplePosition(pos, out NavMeshHit hit, 2f, NavMesh.AllAreas))
            candidates.Add(hit.position);
    }

    Vector3 best = candidates[0];
    int minVisits = int.MaxValue;

    foreach (var point in candidates)
    {
        Vector2Int cell = new Vector2Int(Mathf.FloorToInt(point.x / cellSize), Mathf.FloorToInt(point.z / cellSize));
        visitCounts.TryGetValue(cell, out int visits);
        if (visits < minVisits) { minVisits = visits; best = point; }
    }
    return best;
}

func _build_search_waypoints() -> Array[Vector3]:
    # First visit the last known position, then fan outward
    var points: Array[Vector3] = []
    points.append(last_known_player_pos)

    var base_dir = (last_known_player_pos - global_position).normalized()
    var angles   = [-60.0, -20.0, 20.0, 60.0]
    for a in angles:
        var dir = base_dir.rotated(Vector3.UP, deg_to_rad(a))
        points.append(last_known_player_pos + dir * randf_range(2.5, 5.0))

    return points

